DO $$
DECLARE
    CREATED_AT timestamp := now();
    CREATED_BY text := 'Run:ai';

    THUMBNAIL_LLAMA_32_1B bytea := 'data:image/png;base64,';

    THUMBNAIL_LLAMA_32_3B bytea := 'data:image/png;base64,';

    THUMBNAIL_LLAMA_31_8B bytea := 'data:image/png;base64,';

    THUMBNAIL_MISTRAL_7B  bytea := 'data:image/png;base64,';

    THUMBNAIL_GEMMA_2_2B  bytea := 'data:image/png;base64,';

    THUMBNAIL_GEMMA_2_9B  bytea := 'data:image/png;base64,';

    uuid_model_llama_32_1b uuid := '44ff0958-ccb7-4b2e-ab0c-34b8d2e791a0';
    uuid_model_llama_32_3b uuid := 'f5bec8a6-5fa0-4c24-b325-c0533cbcf2b0';
    uuid_model_llama_31_8b uuid := '207d8167-e1df-436d-9f0b-67ccb598a589';
    uuid_model_mistral_7b uuid := 'c4e0d0cb-ef7b-4f61-9e7a-5755d7c2f030';
    uuid_model_gemma_2_2b uuid := '63433927-6db7-4d79-b629-44aaa9f6b8e4';
    uuid_model_gemma_2_9b uuid := '4950793a-5053-46c6-808e-8441d2b1f492';

    -- uuid of the existing environment asset
    uuid_environment_llm_server uuid := 'a50ef834-4008-4a3a-9ac8-bfc9c177f5e4';

    -- uuid of existing model assets that we need to update or delete
    uuid_model_falcon_7b uuid := 'c6accd0c-3652-4975-ba11-7c9e3e05c7dd';
    uuid_model_falcon_40b uuid := 'b074bd87-6c31-41fa-89f2-16b470d46d29';
BEGIN
    BEGIN
        INSERT INTO assets_metadata ("id", "kind", "scope", "name", "created_by", "created_at", "updated_by", "updated_at") VALUES
            (uuid_model_llama_32_1b, 'model', 'system', 'llama-32-1b-instruct', CREATED_BY, CREATED_AT, CREATED_BY, CREATED_AT),
            (uuid_model_llama_32_3b, 'model', 'system', 'llama-32-3b-instruct', CREATED_BY, CREATED_AT, CREATED_BY, CREATED_AT),
            (uuid_model_llama_31_8b, 'model', 'system', 'llama-31-8b-instruct', CREATED_BY, CREATED_AT, CREATED_BY, CREATED_AT),
            (uuid_model_mistral_7b, 'model', 'system', 'mistral-7b', CREATED_BY, CREATED_AT, CREATED_BY, CREATED_AT),
            (uuid_model_gemma_2_2b, 'model', 'system', 'gemma-2-2b-it', CREATED_BY, CREATED_AT, CREATED_BY, CREATED_AT),
            (uuid_model_gemma_2_9b, 'model', 'system', 'gemma-2-9b-it', CREATED_BY, CREATED_AT, CREATED_BY, CREATED_AT);

        INSERT INTO assets_model ("asset_id", "title", "description", "thumbnail", "huggingface_id", "license", "environment_asset_id") VALUES
            (uuid_model_llama_32_1b, 'Llama-3.2-1B-Instruct',
             'Llama-3.2-1B Instruct by Meta is a multilingual text-generation model with 1.24B parameters, using BF16 precision. Optimized for chat-based and summarization tasks, it’s ideal for dialogue applications in eight languages.',
             THUMBNAIL_LLAMA_32_1B, 'meta-llama/Llama-3.2-1B-Instruct', '', uuid_environment_llm_server),
            (uuid_model_llama_32_3b, 'Llama-3.2-3B-Instruct',
            'Llama-3.2-3B-Instruct by Meta is a 3.21B parameter model optimized for multilingual dialogue and text generation. Built with BF16 precision, it excels in summarization and agentic retrieval across 8 languages, ideal for chatbot and assistant applications.',
             THUMBNAIL_LLAMA_32_3B, 'meta-llama/Llama-3.2-3B-Instruct', '', uuid_environment_llm_server),
            (uuid_model_llama_31_8b, 'Llama-3.1-8B-Instruct',
            'Llama 3.1-8B Instruct (by Meta) is optimized for multilingual dialogue. It offers 8B parameters and BF16 precision, ideal for conversational AI and general-purpose text generation, excelling in multilingual tasks.',
             THUMBNAIL_LLAMA_31_8B, 'meta-llama/Llama-3.1-8B-Instruct', '', uuid_environment_llm_server),
            (uuid_model_mistral_7b, 'Mistral-7B-Instruct',
            'The Mistral-7B-Instruct-v0.3, by Mistral AI, is a 7.25B parameter model fine-tuned for instruction-following tasks. Using BF16 precision, it excels in text generation, function calling, and conversational use cases, ideal for inference endpoints.',
             THUMBNAIL_MISTRAL_7B, 'mistralai/Mistral-7B-Instruct-v0.3', '', uuid_environment_llm_server),
            (uuid_model_gemma_2_2b, 'Gemma-2-2B-it',
            'Gemma-2 2B by Google is a lightweight LLM optimized for text generation tasks like conversational AI and summarization. With 2.61B parameters and BF16 precision, it’s designed for high-performance deployment on limited-resource environments.',
             THUMBNAIL_GEMMA_2_2B, 'google/gemma-2-2b-it', '', uuid_environment_llm_server),
            (uuid_model_gemma_2_9b, 'Gemma-2-9B-it',
            'Gemma 2 9B by Google is a BF16 9.24B parameter model, designed for versatile text generation tasks such as summarization and reasoning. It’s lightweight enough for resource-limited environments and is built on Gemini’s advanced LLM architecture.',
             THUMBNAIL_GEMMA_2_9B, 'google/gemma-2-9b-it', '', uuid_environment_llm_server);

            -- delete falcon 40b
            DELETE FROM assets_model
            WHERE asset_id = uuid_model_falcon_40b;

            DELETE FROM assets_metadata
            WHERE id = uuid_model_falcon_40b;

            -- update title of falcon 7b
            UPDATE assets_model
            SET title = 'Falcon-7B-Instruct'
            WHERE asset_id = uuid_model_falcon_7b;

    EXCEPTION
        WHEN unique_violation THEN
            -- do nothing, already exists
            RAISE NOTICE 'Assets already exist, skipping';
    END;
END $$;
